section.sourcecode:
// T: 送信間隔。1 / OC-Maximum-Rate に設定
// TAU: 許容パラメーター
// ta: 直近の到着の到着時刻
// LCT: サーバーに送信された最後の Diameter リクエストの
//      到着時刻
//      （最初の到着時刻で初期化）
// X: リーキーバケットカウンターの現在値（TAU0 で
//    初期化）

// 直近の到着の後、補助変数 Xp を計算
Xp = X - (ta - LCT);

if (Xp <= TAU) {
  // Diameter リクエストを送信
  // X と LCT を更新
  X = max (0, Xp) + T;
  LCT = ta;
} else {
  // Diameter リクエストを拒否
  // X と LCT は更新しない
}

 // T: 送信間隔。1 / OC-Maximum-Rate に設定
 // TAU1: 優先度なしの Diameter リクエストの許容パラメーター
 // TAU2: 優先度ありの Diameter リクエストの許容パラメーター
 // ta: 直近の到着の到着時刻
 // LCT: サーバーに送信された最後の Diameter リクエストの
 //      到着時刻
 //      （最初の到着時刻で初期化）
 // X: リーキーバケットカウンターの現在値（TAU0 で
 //    初期化）

 // 直近の到着の後、補助変数 Xp を計算
 Xp = X - (ta - LCT);

if (AnyRequestReceived && Xp <= TAU1) || (PriorityRequestReceived &&
 Xp <= TAU2 && Xp > TAU1) {
   // Diameter リクエストを送信
   // X と LCT を更新
   X = max (0, Xp) + T;
   LCT = ta;
 } else {
   // Diameter リクエストに軽減処理を適用
   // X と LCT は更新しない
 }
